data = [3, 1, 4, 1, 5, 9, 2, 6, 5, 3, 5, 8, 9, 7, 9, 3, 2, 3, 8, 4]
freq = {}
for x in data:
    freq[x] = freq.get(x, 0)+1
print('Значение | Частота | График')
for x in sorted(freq):
    print(x, '|', freq[x], '|', '█'*freq[x])

grades = [55, 72, 68, 91, 43, 77, 85, 62, 70, 88, 51, 79, 66, 94, 73, 58, 81, 65, 90, 74, 69, 83, 57, 76, 88, 61, 95, 71, 67, 84, 53, 78, 64, 92, 75, 60, 87, 70, 82, 48]
freq = {start:0 for start in range(40,100,10)}
for grade in grades:
    freq[grade//10*10] += 1
for start,count in freq.items():
    print(f'{start}–{start+9} | '+ '█'*count)
best = max(freq,key=freq.get)
print(f'Самая популярная группа: {best}–{best+9} ({freq[best]} студентов)')
